-- Quantek Instruments headspace O2/CO2 analyzers (10 products): Q20/Q21/Q22, Q30/Q31/Q32, 901, 902P, 905, Q3.
-- Run once in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again.
alter table products add column if not exists features jsonb not null default '[]'::jsonb;
insert into brands (name, slug, website_url) values ('Quantek Instruments', 'quantek-instruments', 'https://www.quantekinstruments.com/')
on conflict (slug) do nothing;
insert into categories (name, slug, sort_order) values ('Equipment','equipment',5) on conflict (slug) do nothing;

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('QUANTEK-Q20', 'Quantek Q20 Portable Oxygen (O₂) Analyzer', 'quantek-q20-portable-oxygen-o2-analyzer', 'The Quantek Q20 is a lightweight (under 1 kg), battery-operated headspace analyzer from the Q20 Series that measures Oxygen (O₂) in packages, processes and containers. It has a colour display, menu-driven setup and calibration, a built-in sample pump and on-board data storage. Used for modified atmosphere (MAP) and gas-flushed food packages such as meats, snack foods, fresh vegetables, coffee, nuts, fruit, dairy and ready meals, and for spot checks of processes such as cell culture incubators.', '[["Model", "Q20"], ["Series", "Q20 Series (portable)"], ["Gases measured", "Oxygen (O₂)"], ["O₂ sensor", "Proprietary electrochemical, 5-year life, not heated, unaffected by CO₂"], ["O₂ range", "0 – 25% or 0 – 100%"], ["O₂ sensitivity / detection limit", "0.1% O₂"], ["O₂ response time", "5 s to 95%, 17 s to final reading"], ["O₂ accuracy", "0.1% O₂ or 1% of reading, whichever is greater"], ["O₂ calibration", "Weekly, with room air (20.9% O₂)"], ["Sample pump", "Miniature diaphragm, menu-driven timing (timed, cycling, continuous), ~5 cc/s, rated 5,000 h"], ["Sampling assembly", "Probe/needle holder with luer needle, disposable filter, 1/16\" PTFE tubing; optional process tube probe"], ["Display", "Colour TFT 320 × 240, 2.6 in"], ["Data storage", "100,000 values with date/time, CSV export to USB drive"], ["Hold function", "Freezes the final reading for 5 s"], ["Battery", "Internal NiMH (6 × AA, 2000 mAh), about 12 h typical use; charger with international plugs"], ["Size", "203 × 51 × 178 mm (8 × 2 × 7 in)"], ["Weight", "0.9 kg (2 lb)"], ["Warranty", "2 years, parts and labour"], ["Included", "Sample probe assembly, 2 luer needles, 200 foam septa, 2 particulate filters, 2 Moisture Guard filters, carry case"], ["Origin", "Made in the U.S.A."]]', '["Fast-response sensors for routine MAP package testing", "Built-in sample pump with adjustable timing", "Stores 100,000 readings with date and time; CSV export to USB", "Hold function freezes the final reading", "5-year oxygen sensor, no routine maintenance", "Made in the U.S.A., 2-year warranty", "Rechargeable battery, about 12 hours of use"]', '/products/quantek/q20-series.jpg'),
  ('QUANTEK-Q21', 'Quantek Q21 Portable Carbon Dioxide (CO₂) Analyzer', 'quantek-q21-portable-carbon-dioxide-co2-analyzer', 'The Quantek Q21 is a lightweight (under 1 kg), battery-operated headspace analyzer from the Q20 Series that measures Carbon Dioxide (CO₂) in packages, processes and containers. It has a colour display, menu-driven setup and calibration, a built-in sample pump and on-board data storage. Used for modified atmosphere (MAP) and gas-flushed food packages such as meats, snack foods, fresh vegetables, coffee, nuts, fruit, dairy and ready meals, and for spot checks of processes such as cell culture incubators.', '[["Model", "Q21"], ["Series", "Q20 Series (portable)"], ["Gases measured", "Carbon Dioxide (CO₂)"], ["CO₂ sensor", "NDIR (infrared)"], ["CO₂ range", "0 – 20% or 0 – 100%"], ["CO₂ sensitivity / detection limit", "0.1% (0.01% on 0 – 20% range)"], ["CO₂ response time", "15 s to 95%, 20 s to final reading"], ["CO₂ accuracy", "0.2% CO₂ or 1% of reading, whichever is greater (0 – 100% range)"], ["CO₂ calibration", "Every 12 months, calibration gas recommended"], ["Sample pump", "Miniature diaphragm, menu-driven timing (timed, cycling, continuous), ~5 cc/s, rated 5,000 h"], ["Sampling assembly", "Probe/needle holder with luer needle, disposable filter, 1/16\" PTFE tubing; optional process tube probe"], ["Display", "Colour TFT 320 × 240, 2.6 in"], ["Data storage", "100,000 values with date/time, CSV export to USB drive"], ["Hold function", "Freezes the final reading for 5 s"], ["Battery", "Internal NiMH (6 × AA, 2000 mAh), about 12 h typical use; charger with international plugs"], ["Size", "203 × 51 × 178 mm (8 × 2 × 7 in)"], ["Weight", "0.9 kg (2 lb)"], ["Warranty", "2 years, parts and labour"], ["Included", "Sample probe assembly, 2 luer needles, 200 foam septa, 2 particulate filters, 2 Moisture Guard filters, carry case"], ["Origin", "Made in the U.S.A."]]', '["Fast-response sensors for routine MAP package testing", "Built-in sample pump with adjustable timing", "Stores 100,000 readings with date and time; CSV export to USB", "Hold function freezes the final reading", "5-year oxygen sensor, no routine maintenance", "Made in the U.S.A., 2-year warranty", "Rechargeable battery, about 12 hours of use"]', '/products/quantek/q20-series.jpg'),
  ('QUANTEK-Q22', 'Quantek Q22 Portable O₂/CO₂ Analyzer', 'quantek-q22-portable-o2-co2-analyzer', 'The Quantek Q22 is a lightweight (under 1 kg), battery-operated headspace analyzer from the Q20 Series that measures O₂/CO₂ in packages, processes and containers. It has a colour display, menu-driven setup and calibration, a built-in sample pump and on-board data storage. Used for modified atmosphere (MAP) and gas-flushed food packages such as meats, snack foods, fresh vegetables, coffee, nuts, fruit, dairy and ready meals, and for spot checks of processes such as cell culture incubators.', '[["Model", "Q22"], ["Series", "Q20 Series (portable)"], ["Gases measured", "O₂/CO₂"], ["O₂ sensor", "Proprietary electrochemical, 5-year life, not heated, unaffected by CO₂"], ["O₂ range", "0 – 25% or 0 – 100%"], ["O₂ sensitivity / detection limit", "0.1% O₂"], ["O₂ response time", "5 s to 95%, 17 s to final reading"], ["O₂ accuracy", "0.1% O₂ or 1% of reading, whichever is greater"], ["O₂ calibration", "Weekly, with room air (20.9% O₂)"], ["CO₂ sensor", "NDIR (infrared)"], ["CO₂ range", "0 – 20% or 0 – 100%"], ["CO₂ sensitivity / detection limit", "0.1% (0.01% on 0 – 20% range)"], ["CO₂ response time", "15 s to 95%, 20 s to final reading"], ["CO₂ accuracy", "0.2% CO₂ or 1% of reading, whichever is greater (0 – 100% range)"], ["CO₂ calibration", "Every 12 months, calibration gas recommended"], ["Sample pump", "Miniature diaphragm, menu-driven timing (timed, cycling, continuous), ~5 cc/s, rated 5,000 h"], ["Sampling assembly", "Probe/needle holder with luer needle, disposable filter, 1/16\" PTFE tubing; optional process tube probe"], ["Display", "Colour TFT 320 × 240, 2.6 in"], ["Data storage", "100,000 values with date/time, CSV export to USB drive"], ["Hold function", "Freezes the final reading for 5 s"], ["Battery", "Internal NiMH (6 × AA, 2000 mAh), about 12 h typical use; charger with international plugs"], ["Size", "203 × 51 × 178 mm (8 × 2 × 7 in)"], ["Weight", "0.9 kg (2 lb)"], ["Warranty", "2 years, parts and labour"], ["Included", "Sample probe assembly, 2 luer needles, 200 foam septa, 2 particulate filters, 2 Moisture Guard filters, carry case"], ["Origin", "Made in the U.S.A."]]', '["Measures oxygen and carbon dioxide together", "Fast-response sensors for routine MAP package testing", "Built-in sample pump with adjustable timing", "Stores 100,000 readings with date and time; CSV export to USB", "Hold function freezes the final reading", "5-year oxygen sensor, no routine maintenance", "Made in the U.S.A., 2-year warranty", "Rechargeable battery, about 12 hours of use"]', '/products/quantek/q20-series.jpg'),
  ('QUANTEK-Q30', 'Quantek Q30 Desktop Oxygen (O₂) Analyzer', 'quantek-q30-desktop-oxygen-o2-analyzer', 'The Quantek Q30 is a desktop/benchtop headspace analyzer from the Q30 Series that measures Oxygen (O₂) in packages, bottles and containers. It has a colour display, menu-driven setup and calibration, a built-in sample pump and on-board data storage, and runs from a 12 V DC wall adapter. Used for modified atmosphere (MAP) and gas-flushed food packages such as meats, snack foods, fresh vegetables, coffee, nuts, fruit, dairy and ready meals, and for spot checks of processes such as cell culture incubators.', '[["Model", "Q30"], ["Series", "Q30 Series (desktop)"], ["Gases measured", "Oxygen (O₂)"], ["O₂ sensor", "Proprietary electrochemical, 5-year life, not heated, unaffected by CO₂"], ["O₂ range", "0 – 25% or 0 – 100%"], ["O₂ sensitivity / detection limit", "0.1% O₂"], ["O₂ response time", "5 s to 95%, 17 s to final reading"], ["O₂ accuracy", "0.1% O₂ or 1% of reading, whichever is greater"], ["O₂ calibration", "Weekly, with room air (20.9% O₂)"], ["Sample pump", "Miniature diaphragm, menu-driven timing (timed, cycling, continuous), ~5 cc/s, rated 5,000 h"], ["Sampling assembly", "Probe/needle holder with luer needle, disposable filter, 1/16\" PTFE tubing; optional process tube probe"], ["Display", "Colour TFT 320 × 240, 2.6 in"], ["Data storage", "100,000 values with date/time, CSV export to USB drive"], ["Hold function", "Freezes the final reading for 5 s"], ["Power", "Wall adapter, 110/240 V AC to 12 V DC"], ["Size", "203 × 51 × 178 mm (8 × 2 × 7 in)"], ["Weight", "5 lb"], ["Warranty", "2 years, parts and labour"], ["Included", "Sample probe assembly, 2 luer needles, 200 foam septa, 2 particulate filters, 2 Moisture Guard filters"], ["Origin", "Made in the U.S.A."]]', '["Fast-response sensors for routine MAP package testing", "Built-in sample pump with adjustable timing", "Stores 100,000 readings with date and time; CSV export to USB", "Hold function freezes the final reading", "5-year oxygen sensor, no routine maintenance", "Made in the U.S.A., 2-year warranty"]', '/products/quantek/q30-series.jpg'),
  ('QUANTEK-Q31', 'Quantek Q31 Desktop Carbon Dioxide (CO₂) Analyzer', 'quantek-q31-desktop-carbon-dioxide-co2-analyzer', 'The Quantek Q31 is a desktop/benchtop headspace analyzer from the Q30 Series that measures Carbon Dioxide (CO₂) in packages, bottles and containers. It has a colour display, menu-driven setup and calibration, a built-in sample pump and on-board data storage, and runs from a 12 V DC wall adapter. Used for modified atmosphere (MAP) and gas-flushed food packages such as meats, snack foods, fresh vegetables, coffee, nuts, fruit, dairy and ready meals, and for spot checks of processes such as cell culture incubators.', '[["Model", "Q31"], ["Series", "Q30 Series (desktop)"], ["Gases measured", "Carbon Dioxide (CO₂)"], ["CO₂ sensor", "NDIR (infrared)"], ["CO₂ range", "0 – 20% or 0 – 100%"], ["CO₂ sensitivity / detection limit", "0.1% (0.01% on 0 – 20% range)"], ["CO₂ response time", "15 s to 95%, 20 s to final reading"], ["CO₂ accuracy", "0.2% CO₂ or 1% of reading, whichever is greater (0 – 100% range)"], ["CO₂ calibration", "Every 12 months, calibration gas recommended"], ["Sample pump", "Miniature diaphragm, menu-driven timing (timed, cycling, continuous), ~5 cc/s, rated 5,000 h"], ["Sampling assembly", "Probe/needle holder with luer needle, disposable filter, 1/16\" PTFE tubing; optional process tube probe"], ["Display", "Colour TFT 320 × 240, 2.6 in"], ["Data storage", "100,000 values with date/time, CSV export to USB drive"], ["Hold function", "Freezes the final reading for 5 s"], ["Power", "Wall adapter, 110/240 V AC to 12 V DC"], ["Size", "203 × 51 × 178 mm (8 × 2 × 7 in)"], ["Weight", "5 lb"], ["Warranty", "2 years, parts and labour"], ["Included", "Sample probe assembly, 2 luer needles, 200 foam septa, 2 particulate filters, 2 Moisture Guard filters"], ["Origin", "Made in the U.S.A."]]', '["Fast-response sensors for routine MAP package testing", "Built-in sample pump with adjustable timing", "Stores 100,000 readings with date and time; CSV export to USB", "Hold function freezes the final reading", "5-year oxygen sensor, no routine maintenance", "Made in the U.S.A., 2-year warranty"]', '/products/quantek/q30-series.jpg'),
  ('QUANTEK-Q32', 'Quantek Q32 Desktop O₂/CO₂ Analyzer', 'quantek-q32-desktop-o2-co2-analyzer', 'The Quantek Q32 is a desktop/benchtop headspace analyzer from the Q30 Series that measures O₂/CO₂ in packages, bottles and containers. It has a colour display, menu-driven setup and calibration, a built-in sample pump and on-board data storage, and runs from a 12 V DC wall adapter. Used for modified atmosphere (MAP) and gas-flushed food packages such as meats, snack foods, fresh vegetables, coffee, nuts, fruit, dairy and ready meals, and for spot checks of processes such as cell culture incubators.', '[["Model", "Q32"], ["Series", "Q30 Series (desktop)"], ["Gases measured", "O₂/CO₂"], ["O₂ sensor", "Proprietary electrochemical, 5-year life, not heated, unaffected by CO₂"], ["O₂ range", "0 – 25% or 0 – 100%"], ["O₂ sensitivity / detection limit", "0.1% O₂"], ["O₂ response time", "5 s to 95%, 17 s to final reading"], ["O₂ accuracy", "0.1% O₂ or 1% of reading, whichever is greater"], ["O₂ calibration", "Weekly, with room air (20.9% O₂)"], ["CO₂ sensor", "NDIR (infrared)"], ["CO₂ range", "0 – 20% or 0 – 100%"], ["CO₂ sensitivity / detection limit", "0.1% (0.01% on 0 – 20% range)"], ["CO₂ response time", "15 s to 95%, 20 s to final reading"], ["CO₂ accuracy", "0.2% CO₂ or 1% of reading, whichever is greater (0 – 100% range)"], ["CO₂ calibration", "Every 12 months, calibration gas recommended"], ["Sample pump", "Miniature diaphragm, menu-driven timing (timed, cycling, continuous), ~5 cc/s, rated 5,000 h"], ["Sampling assembly", "Probe/needle holder with luer needle, disposable filter, 1/16\" PTFE tubing; optional process tube probe"], ["Display", "Colour TFT 320 × 240, 2.6 in"], ["Data storage", "100,000 values with date/time, CSV export to USB drive"], ["Hold function", "Freezes the final reading for 5 s"], ["Power", "Wall adapter, 110/240 V AC to 12 V DC"], ["Size", "203 × 51 × 178 mm (8 × 2 × 7 in)"], ["Weight", "5 lb"], ["Warranty", "2 years, parts and labour"], ["Included", "Sample probe assembly, 2 luer needles, 200 foam septa, 2 particulate filters, 2 Moisture Guard filters"], ["Origin", "Made in the U.S.A."]]', '["Measures oxygen and carbon dioxide together", "Fast-response sensors for routine MAP package testing", "Built-in sample pump with adjustable timing", "Stores 100,000 readings with date and time; CSV export to USB", "Hold function freezes the final reading", "5-year oxygen sensor, no routine maintenance", "Made in the U.S.A., 2-year warranty"]', '/products/quantek/q30-series.jpg'),
  ('QUANTEK-905', 'Quantek Model 905 Benchtop Oxygen Analyzer', 'quantek-model-905-benchtop-oxygen-analyzer', 'The Quantek Model 905 is a benchtop, portable oxygen analyzer for measuring residual oxygen in gas-flushed (CAP/MAP) food packages and other containers. It is easy for non-technical staff to use in the lab or on the packaging line, and its proprietary sensor lasts 4–5 years and is not poisoned by high CO₂.', '[["Model", "905"], ["Range", "0.0 – 100% oxygen"], ["Resolution", "0.1% O₂ (optional 0.01%)"], ["Accuracy", "0.1% below 10% O₂; 0.05% below 1% (with 0.01% resolution)"], ["Response time", "15 – 17 s to T95"], ["Drift", "Less than 0.1% per month"], ["Sensor", "Proprietary electrochemical cell, 4 – 5 year life, works down to −13 °C"], ["Sample pump", "Internal, adjustable timer 2 – 12 s, ~5 cc/s"], ["Sampling assembly", "Probe with male luer connection for side-port needle, PTFE tubing"], ["Calibration", "Room air; adjusters on back; recommended yearly"], ["Power", "100 – 240 V, 50 – 60 Hz power supply; optional internal 12 V NiMH battery (10 – 14 h)"], ["Size", "249 × 102 × 254 mm (9.8 × 4 × 10 in)"], ["Weight", "3.6 kg (8 lb)"], ["Warranty", "2 years, parts and labour"], ["Included", "200 foam septa, 4 liquid blocking filters, 2 needles, NIST traceable calibration certificate"]]', '["Fast response, final reading in 7 – 8 seconds", "Range 0 – 100% oxygen, calibrates with room air", "Long-life 4 – 5 year sensor", "Internal sampling pump", "Optional battery operation", "Low running and maintenance cost"]', '/products/quantek/model-905.jpg'),
  ('QUANTEK-901', 'Quantek Model 901 Handheld Headspace Oxygen Analyzer', 'quantek-model-901-handheld-headspace-oxygen-analyzer', 'The Quantek Model 901 is a battery-operated, portable headspace oxygen analyzer weighing about 450 g. Attach a foam septum to the package, insert the needle and press the pump button; the residual oxygen reading appears within 15–20 seconds. Its long-life sensor is expected to last 5 years.', '[["Model", "901"], ["Range", "0.0 – 100% oxygen"], ["Resolution", "0.1% O₂"], ["Accuracy", "±0.1% (below 10% O₂)"], ["Minimum detection limit", "0.1%"], ["Drift", "Less than 1% per month"], ["Sensor", "Proprietary electrochemical cell, 4 – 5 year life"], ["Sample pump", "Internal, ~5 cc/s, 2 – 12 s adjustable timer"], ["Sampling assembly", "Probe with male luer connection for side-port needle, PTFE tubing"], ["Calibration", "Room air; SPAN and ZERO adjustment; at least once a year"], ["Power", "4 × AA NiMH rechargeable (auto-off after 45 min); charger 100 – 240 V; AA alkaline backup"], ["Battery life", "10 – 14 hours"], ["Size", "200 × 100 × 40 mm"], ["Weight", "450 g (1 lb)"], ["Warranty", "2 years, parts and labour"], ["Standards", "CE, RoHS"], ["Included", "200 foam septa, 2 luer needles, 2 particulate filters, 2 liquid block filters, manual, NIST calibration certificate"]]', '["Handheld and battery powered, about 450 g", "Reading in 15 – 20 seconds", "5-year sensor, unaffected by N₂, CO₂ and hydrocarbons", "Liquid blocking filters protect the analyzer", "Low total cost of ownership"]', '/products/quantek/model-901.jpg'),
  ('QUANTEK-902P', 'Quantek Model 902P O₂/CO₂ Analyzer', 'quantek-model-902p-o2-co2-analyzer', 'The Quantek Model 902P measures oxygen and carbon dioxide in flowing gas samples from chambers, experiments, rooms and process systems. Sample flows through the front panel fitting at 10–1000 cc/min; an optional internal pump draws sample when no flow or pressure is available. It uses a 5-year electrochemical O₂ sensor and a solid-state infrared CO₂ sensor.', '[["Model", "902P"], ["Gases measured", "Oxygen and carbon dioxide"], ["O₂ sensor", "Heavy-duty electrochemical, about 5-year life"], ["CO₂ sensor", "Solid-state infrared (NDIR), microprocessor-linearised up to 100%"], ["Sample flow", "10 – 1000 cc/min (50 cc/min recommended); bypass vents excess pressure"], ["Optional pump", "Internal diaphragm pump, ~5 cc/s, 2 – 12 s timer; optional continuous, cycling or concentration-triggered modes"], ["Moisture protection", "Internal user-replaceable moisture trap filter"], ["Power", "100 – 240 V, 50 – 60 Hz; optional internal 12 V battery"], ["Size", "249 × 102 × 254 mm (9.8 × 4 × 10 in)"], ["Weight", "4.4 kg (9.8 lb)"], ["Warranty", "2 years, parts and labour"], ["Standards", "CE, RoHS"]]', '["Measures O₂ and CO₂ in flowing gas samples", "Accepts 10 – 1000 cc/min without affecting readings", "Optional internal pump with advanced timing modes", "Long-life sensors; CO₂ sensor has no moving parts", "Optional battery operation"]', '/products/quantek/model-902p.jpg'),
  ('QUANTEK-Q3', 'Quantek Q3 Portable CO₂ Analyzer for Incubators', 'quantek-q3-portable-co2-analyzer-incubator', 'The Quantek Q3 is a portable CO₂ analyzer for spot checks of incubators, processes, gas blending and biotech systems. Insert the probe into the incubator sampling port and press the pump button for quick, accurate results. It weighs about 0.9 kg and comes with rechargeable batteries, probe, charger and a hard carry case.', '[["Model", "Q3"], ["CO₂ sensor", "Solid-state infrared (NDIR), no moving parts or consumables"], ["Range", "0 – 20% or 0 – 100% CO₂"], ["Accuracy", "±1% of reading or ±0.2% CO₂, whichever is greater"], ["Minimum detection limit", "0.1% (0 – 100% range) or 0.01% (0 – 20% range)"], ["Controls", "Side adjusters for pump time, CO₂ span and CO₂ zero; no warm-up needed"], ["Calibration", "Every 12 months, calibration gas recommended"], ["Battery life", "10 – 14 hours"], ["Weight", "about 0.9 kg (2 lb)"], ["Warranty", "2 years, parts and labour"], ["Included", "Rechargeable batteries, sample probe, charger, accessories, hard carry case"]]', '["Designed for CO₂ spot checks in incubators", "Infrared sensor with unlimited theoretical life", "No warm-up, simple side adjustments", "Battery powered, 10 – 14 hours", "Carry case included"]', '/products/quantek/model-q3.jpg')
) as v(sku, name, slug, description, specs, features, image_url)
cross join (select id from categories where slug = 'equipment') c
cross join (select id from brands where slug = 'quantek-instruments') b
on conflict (sku) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, specs = excluded.specs,
  features = excluded.features, category_id = excluded.category_id, brand_id = excluded.brand_id, image_url = excluded.image_url, is_active = true;

select name, sku from products where sku like 'QUANTEK-%' order by sku;
